import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'core/router/app_router.dart';import 'core/theme/app_theme.dart';import 'presentation/providers/providers.dart';
void main(){WidgetsFlutterBinding.ensureInitialized();SystemChrome.setPreferredOrientations([DeviceOrientation.portraitUp]);SystemChrome.setSystemUIOverlayStyle(const SystemUiOverlayStyle(statusBarColor:Colors.transparent));runApp(const ProviderScope(child:KinoTvApp()));}
class KinoTvApp extends ConsumerWidget{const KinoTvApp({super.key});@override Widget build(BuildContext context,WidgetRef ref){final router=ref.watch(routerProvider),dark=ref.watch(authProvider).user?.darkMode??true;return MaterialApp.router(title:'KinoTV',debugShowCheckedModeBanner:false,theme:AppTheme.light(),darkTheme:AppTheme.dark(),themeMode:dark?ThemeMode.dark:ThemeMode.light,locale:const Locale('uz'),routerConfig:router);}}
